int main(int argc,char**argv)try{if(argc!=3)return 2;auto input=Scene::load(argv[1]);run(input,argv[2],true);run(generic(input),argv[2],false);auto unused=generic(input);ShapeKeyEdit added;added.name="Retained now-unused endpoint";author_shapekey(unused,unused.active().id,added);auto &o=unused.active();auto binding=std::make_shared<SourceMaterialBindings>(*o.material_bindings);auto frames=std::make_shared<NormalFrameSet>(*binding->normal_frames);frames->current_targets.pop_back();binding->normal_frames=frames;o.material_bindings=binding;auto d=std::make_shared<DeformationState>(*o.deformation);check(!d->expressions,"Unused-target fixture does not erase or fabricate source expression bindings");d->morphs->targets.pop_back();if(!d->morph_weights.empty())d->morph_weights.pop_back();o.deformation=d;unused.validate();run(unused,std::filesystem::path(argv[2])/"retained-unused",false);std::cout<<"PASS "<<checks<<" independent named key checks"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
